#!/usr/bin/env python3
"""
Implementation of the logstat command line tool as specified in SPEC.md.
"""

import sys
import datetime

# Severity order
SEVERITY_ORDER = ['DEBUG', 'INFO', 'WARN', 'ERROR', 'FATAL']
LEVEL_SET = set(SEVERITY_ORDER)


def usage_error(msg="usage error"):
    sys.stderr.write(f"logstat: {msg}\n")
    sys.exit(2)


def input_error(msg="input error"):
    sys.stderr.write(f"logstat: {msg}\n")
    sys.exit(3)


def malformed_error(line_no):
    sys.stderr.write(f"logstat: malformed record on line {line_no}\n")
    sys.exit(4)


def no_records_error():
    sys.stderr.write("logstat: no records matched\n")
    sys.exit(5)


def parse_args(argv):
    # argv: list of arguments excluding script name
    if not argv:
        usage_error()
    subcommand = argv[0]
    if subcommand not in {"count", "top", "span"}:
        usage_error()

    min_level = "DEBUG"
    number = None
    file_path = None

    i = 1
    while i < len(argv):
        token = argv[i]
        # file candidate
        if token != "-" and not token.startswith("-"):
            if file_path is None:
                file_path = token
            else:
                # more than one file
                usage_error()
            i += 1
            continue
        # option
        if not token.startswith("--"):
            usage_error()
        # handle --option=value or --option value
        if '=' in token:
            opt_name, opt_val = token[2:].split('=', 1)
        else:
            opt_name = token[2:]
            if i + 1 >= len(argv):
                usage_error()
            opt_val = argv[i+1]
            i += 1  # skip value
        if opt_name == "min-level":
            if opt_val not in LEVEL_SET:
                usage_error()
            min_level = opt_val
        elif opt_name == "number":
            if subcommand != "top":
                usage_error()
            if not opt_val.isdigit() or int(opt_val) <= 0:
                usage_error()
            number = int(opt_val)
        else:
            usage_error()
        i += 1
    return subcommand, min_level, number, file_path


def read_input(file_path):
    try:
        if file_path is None:
            data = sys.stdin.read()
        else:
            with open(file_path, 'r', encoding='utf-8') as f:
                data = f.read()
    except Exception:
        input_error()
    # splitlines keeps lines without trailing newline; empty last line ok
    return data.splitlines()


def is_blank(line):
    return line.strip(" \t") == ""


def parse_record(line, line_no):
    # returns dict or None if not record
    if line.count('|') < 3:
        return None
    parts = line.split('|', 3)
    if len(parts) < 4:
        return None
    timestamp_str, level, service, message = parts
    # timestamp checks
    if len(timestamp_str) != 20:
        return None
    try:
        dt = datetime.datetime.strptime(timestamp_str, "%Y-%m-%dT%H:%M:%SZ")
    except Exception:
        return None
    # level check
    if level not in LEVEL_SET:
        return None
    # service must not be empty
    if service == "":
        return None
    # message can be anything
    return {
        'timestamp': timestamp_str,
        'datetime': dt,
        'level': level,
        'service': service,
    }


def process_records(lines):
    records = []
    for idx, line in enumerate(lines, start=1):
        if is_blank(line):
            continue
        rec = parse_record(line, idx)
        if rec is None:
            malformed_error(idx)
        records.append(rec)
    return records


def filter_records(records, min_level):
    min_index = SEVERITY_ORDER.index(min_level)
    return [r for r in records if SEVERITY_ORDER.index(r['level']) >= min_index]


def count_summary(records, min_level):
    min_index = SEVERITY_ORDER.index(min_level)
    levels = SEVERITY_ORDER[min_index:]
    counts = {lvl: 0 for lvl in levels}
    for r in records:
        if r['level'] in counts:
            counts[r['level']] += 1
    total = sum(counts.values())
    width = max(len(str(total)), 1)
    out_lines = []
    for lvl in levels:
        out_lines.append(f"{lvl:<5} {counts[lvl]:>{width}}")
    out_lines.append(f"{'TOTAL':<5} {total:{width}}")
    return out_lines


def top_summary(records, number):
    # number is int; if None, default 3
    if number is None:
        number = 3
    if not records:
        return []
    counts = {}
    for r in records:
        counts[r['service']] = counts.get(r['service'], 0) + 1
    items = list(counts.items())
    items.sort(key=lambda x: (-x[1], x[0]))
    items = items[:number]
    name_len = max(len(name) for name, _ in items)
    count_len = max(len(str(cnt)) for _, cnt in items)
    out_lines = []
    for name, cnt in items:
        out_lines.append(f"{name:<{name_len}} {cnt:>{count_len}}")
    return out_lines


def span_summary(records):
    if not records:
        no_records_error()
    # find earliest and latest datetime
    earliest = min(records, key=lambda r: r['datetime'])
    latest = max(records, key=lambda r: r['datetime'])
    secs = int((latest['datetime'] - earliest['datetime']).total_seconds())
    out_lines = []
    out_lines.append(f"{'first':<5} {earliest['timestamp']}")
    out_lines.append(f"{'last':<5} {latest['timestamp']}")
    out_lines.append(f"{'secs':<5} {secs}")
    return out_lines


def main():
    subcommand, min_level, number, file_path = parse_args(sys.argv[1:])
    lines = read_input(file_path)
    records = process_records(lines)
    filtered = filter_records(records, min_level)
    if subcommand == "count":
        out_lines = count_summary(filtered, min_level)
    elif subcommand == "top":
        out_lines = top_summary(filtered, number)
    elif subcommand == "span":
        out_lines = span_summary(filtered)
    else:
        # should not happen due to earlier check
        usage_error()
    # write output
    for line in out_lines:
        sys.stdout.write(line + '\n')

if __name__ == "__main__":
    main()

